package org.formasaloido;
import java.util.*;

/** Interpretations and source regions are separate from extracted geometry. */
public final class ImageScene {
 public static final class Region {
  public final double left,top,right,bottom;public String label,analogy,source;
  public Region(double l,double t,double r,double b,String name,String like,String origin){if(!Double.isFinite(l)||!Double.isFinite(t)||!Double.isFinite(r)||!Double.isFinite(b)||l<0||t<0||r>1||b>1||r-l<.001||b-t<.001)throw new IllegalArgumentException("Región fuera de la imagen");left=l;top=t;right=r;bottom=b;label=clean(name,160);analogy=clean(like,240);source=clean(origin,100);}
  public String description(boolean interpretations){String where=Geometry.position(new Geometry.Point((left+right)*300,(top+bottom)*225));return where+". "+(interpretations?source+": "+(label.isEmpty()?"Sin identificar":label)+". "+(analogy.isEmpty()?"":"Analogía aproximada: "+analogy+". "):"Interpretaciones ocultas. ")+"La región delimita una zona de exploración; su caja no es la silueta del objeto.";}
 }
 public final List<Region> regions=new ArrayList<>();public String overview="Sin interpretación semántica disponible.",source="Geometría extraída";
 public static String clean(Object v,int maximum){String s=v==null?"":v.toString().replaceAll("[\\p{Cntrl}]"," ").trim();return s.substring(0,Math.min(maximum,s.length()));}
 public static ImageScene fromJson(String text,String origin){Object parsed=Json.parse(text);if(!(parsed instanceof Map))throw new IllegalArgumentException("Se esperaba una escena");Map<?,?> root=(Map<?,?>)parsed;ImageScene scene=new ImageScene();scene.source=clean(origin,100);scene.overview=clean(root.get("overview"),1200);Object items=root.get("regions");if(!(items instanceof List)||((List<?>)items).size()>24)throw new IllegalArgumentException("Lista de regiones no válida");for(Object item:(List<?>)items){if(!(item instanceof Map))throw new IllegalArgumentException("Región no válida");Map<?,?> r=(Map<?,?>)item;Object box=r.get("box");if(!(box instanceof List)||((List<?>)box).size()!=4)throw new IllegalArgumentException("Caja no válida");List<?> b=(List<?>)box;scene.regions.add(new Region(number(b.get(0)),number(b.get(1)),number(b.get(2)),number(b.get(3)),clean(r.get("label"),160),clean(r.get("analogy"),240),origin));}return scene;}
 private static double number(Object o){if(!(o instanceof Number))throw new IllegalArgumentException("Coordenada no numérica");return ((Number)o).doubleValue();}
 public String json(){List<Object> items=new ArrayList<>();for(Region r:regions)items.add(Json.object("box",Arrays.asList(r.left,r.top,r.right,r.bottom),"label",r.label,"analogy",r.analogy,"source",r.source));return Json.write(Json.object("overview",overview,"source",source,"regions",items));}
 public void addUnknown(Geometry g,double l,double t,double w,double h){
  for(Geometry.Shape s:g.shapes){if(regions.size()>=48)break;if(s.hole||s.points.isEmpty())continue;double a=1,b=1,c=0,d=0;for(Geometry.Point p:s.points){double x=(p.x-l)/w,y=(p.y-t)/h;a=Math.min(a,x);b=Math.min(b,y);c=Math.max(c,x);d=Math.max(d,y);}double cx=(a+c)/2,cy=(b+d)/2;boolean covered=false;for(Region r:regions)if(!r.source.equals("Geometría extraída")&&cx>=r.left&&cx<=r.right&&cy>=r.top&&cy<=r.bottom){covered=true;break;}if(covered)continue;String like=s.curve?(c-a>d-b?"una forma curva más ancha que alta":"una forma curva más alta que ancha"):(s.points.size()==3?"una figura triangular":"una forma de bordes segmentados");regions.add(new Region(Math.max(0,a-.015),Math.max(0,b-.015),Math.min(1,Math.max(a+.002,c+.015)),Math.min(1,Math.max(b+.002,d+.015)),"Componente sin identificar",like,"Geometría extraída"));}
  if(regions.isEmpty())regions.add(new Region(0,0,1,1,"Imagen completa sin identificar","","Geometría extraída"));
 }
 /** Fits the selected source rectangle; clips crossing segments as open traces, preserving holes fully inside. */
 public static Geometry focus(Geometry g,Region r,double imageLeft,double imageTop,double imageWidth,double imageHeight){double l=imageLeft+r.left*imageWidth,t=imageTop+r.top*imageHeight,w=(r.right-r.left)*imageWidth,h=(r.bottom-r.top)*imageHeight,scale=Math.min(568/w,418/h),ox=(600-w*scale)/2,oy=(450-h*scale)/2;List<Geometry.Shape> shapes=new ArrayList<>();
  for(Geometry.Shape s:g.shapes){boolean all=true;for(Geometry.Point p:s.points)if(p.x<l||p.x>l+w||p.y<t||p.y>t+h)all=false;if(all){List<Geometry.Point> points=new ArrayList<>();for(Geometry.Point p:s.points)points.add(mapped(p,l,t,scale,ox,oy));shapes.add(new Geometry.Shape(points,s.closed,s.curve,s.strokeWidth,s.hole));continue;}
   List<Geometry.Point> run=new ArrayList<>();for(int i=1;i<s.points.size()+(s.closed?1:0);i++){Geometry.Point a=s.points.get(i-1),b=s.points.get(i%s.points.size());double[] range={0,1};double dx=b.x-a.x,dy=b.y-a.y;if(clip(-dx,a.x-l,range)&&clip(dx,l+w-a.x,range)&&clip(-dy,a.y-t,range)&&clip(dy,t+h-a.y,range)){Geometry.Point p=mapped(new Geometry.Point(a.x+range[0]*dx,a.y+range[0]*dy,a.z),l,t,scale,ox,oy),q=mapped(new Geometry.Point(a.x+range[1]*dx,a.y+range[1]*dy,b.z),l,t,scale,ox,oy);if(!run.isEmpty()&&run.get(run.size()-1).distance(p)>.00001){shapes.add(new Geometry.Shape(run,false,s.curve,s.strokeWidth));run=new ArrayList<>();}if(run.isEmpty())run.add(p);run.add(q);}else if(!run.isEmpty()){shapes.add(new Geometry.Shape(run,false,s.curve,s.strokeWidth));run=new ArrayList<>();}}if(!run.isEmpty())shapes.add(new Geometry.Shape(run,false,s.curve,s.strokeWidth));
  }return new Geometry(g.seed,shapes);
 }
 private static Geometry.Point mapped(Geometry.Point p,double l,double t,double s,double x,double y){return new Geometry.Point(x+(p.x-l)*s,y+(p.y-t)*s,p.z);}
 private static boolean clip(double p,double q,double[] range){if(p==0)return q>=0;double v=q/p;if(p<0){if(v>range[1])return false;range[0]=Math.max(range[0],v);}else{if(v<range[0])return false;range[1]=Math.min(range[1],v);}return true;}
}
